</main></div></div><script>(()=>{const sidebar=document.querySelector('.admin-sidebar');const toggle=document.querySelector('.sidebar-toggle');const close=document.querySelector('.sidebar-close');if(!sidebar||!toggle)return;const setOpen=open=>{sidebar.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close admin navigation':'Open admin navigation')};toggle.setAttribute('aria-expanded','false');toggle.addEventListener('click',()=>setOpen(!sidebar.classList.contains('open')));close?.addEventListener('click',()=>setOpen(false));document.addEventListener('keydown',event=>{if(event.key==='Escape')setOpen(false)});})();</script></body></html>
